{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Ibrutinib, the closest high-similarity analogue sharing the acrylamide-piperidine and phenoxyphenyl BTK-inhibitor scaffold, showed a CSF/plasma ratio of 28.7% in humans, indicating high BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Radiolabeled ibrutinib (FK886) demonstrated good and quick brain penetration in rats, with a brain concentration of 1412 ng eq/g tissue 5 min after i.v. administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tirabrutinib, a close analogue with the same pyrimidinone-phenoxyphenyl core, was rapidly absorbed into rat brain after oral dosing and exhibited an unbound brain-to-plasma ratio of 8.5% at Cmax, classified as permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The active metabolite of ibrutinib, PCI-45227, crossed the blood-brain barrier with quantifiable CSF levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A structurally related BTK inhibitor achieved an acceptable Kp,uu of 0.37 in a rat constant-infusion study, supporting meaningful brain exposure for this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is zanubrutinib, a BTK inhibitor closely related to ibrutinib and tirabrutinib. Direct human and rodent evidence for these close analogues demonstrates meaningful CNS exposure via CSF/plasma ratios, brain concentrations, and Kp,uu measurements, supporting a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or Kp,uu measurement for zanubrutinib itself is present in this evidence set.",
    "Efflux-transporter liability for the query is not directly assessed, though close analogues show net CNS penetration despite possible transporter interactions.",
    "Quantitative human brain exposure for the exact query molecule is not directly reported here."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

